,"label":"badge_type","default-value":"""","required":false,"metadata":{"type":"String","list":false,"items":[],"use_items":false},"id":"07613e6845ed48ea9f46252f90f0df3b","type":"String"},{"name":"user_type_sys_id","label":"user_type_sys_id","default-value":""777f8ed51bbc8210759455342a4bcb58"","required":true,"metadata":{"type":"String","list":false,"items":[],"use_items":false},"id":"20bddc1f22ea48faa4912e31d8fd713f","type":"String"}],"return-values-mapping":[]},"domain":"global","topic_type":"TOPIC_BLOCK","channels":[],"dialog_acts_enabled":false,"id":"9728b0232bffee10d4dffd74ce91bfcc","name":"_PRVW__cab7507baca0475bbef8a814f8e0f670","key_phrases":[],"nlu_provider":"","nlu_model":"","nlu_model_label":"","nlu_intent":"","nlu_intent_label":"","flexible_conversation_switching":true,"autopilot_topic":false,"design_categories":[],"triggerable_by_notification":false,"description":"This Topic Block is responsible for assigning badges to users within the system. It supports multiple badge types, including: Temporary Badge, Permanent Badge, Mobile Credential
Inputs:
User ID: The unique identifier of the user receiving the badge.
Badge Type: Type of the badge to be assigned.
Output:
Response String: A structured string confirming the result of the badge assignment operation.","model_type":"llm","foundational":false,"modify_confirmation_enabled":false,"context_profiles":[],"title":"Guardian Badge Assignment Topic Block","library":true,"csTopicId":"63bc7ca72bffee10d4dffd74ce91bf34","readOnly":false,"nluMapping":"[]"}

